WITH cleaned AS (SELECT *, TRIM(name) clean_name, LOWER(city) city_lower, COALESCE(city, 'DIRECT') resolved_city FROM customers WHERE signup_date >= DATE '2023-07-30') SELECT DATE_TRUNC('MONTH', signup_date) AS activity_month, country, DATE_TRUNC('QUARTER', signup_date) AS quarter_start, COUNT(*) FILTER (WHERE city = 'Tokyo') AS tokyo_rows, COUNT_IF(country = 'DE') AS de_events FROM cleaned GROUP BY GROUPING SETS ((DATE_TRUNC('MONTH', signup_date), country, DATE_TRUNC('QUARTER', signup_date)), (DATE_TRUNC('MONTH', signup_date), country), ()) HAVING COUNT(*) FILTER (WHERE city = 'Tokyo') > 1;
